import { request_channel_access } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { update_audit_logs } from "@/mixins/AuditLogActions.js";
export default {
  props: {
    requestAccessDialog: {
      type: Boolean,
      default: false
    },
    rowInfo: {
      type: Object,
      default: () => ({})
    }
  },
  mixins: [update_audit_logs],
  data() {
    return {
      loading: false
    };
  },
  methods: {
    async request_access() {
      this.loading = true;
      const data = this.$store.getters.GetUserObj;
      try {
        const result = await API.graphql(graphqlOperation(request_channel_access, {
          input: {
            team_id: this.rowInfo.team_id,
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id
          }
        }));
        const response = JSON.parse(result.data.request_channel_access);
        this.loading = false;
        if (response.Status === "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("clicked"); // Close dialog on success
        } else {
          this.$emit("errorMsg", response.Message || "Failed to request access");
        }
      } catch (error) {
        this.loading = false;
        const errorMessage = error.errors?.[0]?.message || error.message || "An unexpected error occurred";
        this.$emit("errorMsg", errorMessage);
      }
    }
  }
};
